const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for Punjab and Haryana
  const punjab = ee.Geometry.Rectangle([73.5, 29.5, 76.5, 32.5]);
  const haryana = ee.Geometry.Rectangle([76.0, 27.0, 77.5, 30.0]);
  const combinedRegion = punjab.union(haryana);

  // 2. Define time period: November 2024
  const startDate = '2024-11-01';
  const endDate = '2024-11-30';

  // 3. Load VIIRS active fire detection data
  const viirsFires = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGT')
    .filterDate(startDate, endDate)
    .filterBounds(combinedRegion);

  // 4. Check if collection is empty
  const collectionSize = viirsFires.size().getInfo();
  console.log(`VIIRS Images found (Nov 2024): ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No VIIRS data available for November 2024');
    console.log('C1');
    return;
  }

  // 5. Count fire detections using the 'confidence' band
  // VIIRS VNP14IMGT has 'confidence' band (0-100) where higher values indicate confident fire detections
  const firePixels = viirsFires
    .select('confidence')
    .map(function(img) {
      return img.gt(50); // Filter for confidence > 50 (moderate to high confidence)
    })
    .sum();

  // 6. Count total fire detections in the region
  const fireCount = firePixels.reduceRegion(
    ee.Reducer.sum(),
    combinedRegion,
    1000,
    1e9
  ).get('confidence').getInfo();

  console.log(`Fire detections in Punjab & Haryana (Nov 2024): ${fireCount}`);

  // 7. Validate result
  if (fireCount === null || isNaN(fireCount)) {
    console.log('C3');
    return;
  }

  // 8. Compare to 20,000 threshold
  const threshold = 20000;
  if (fireCount < threshold) {
    console.log(`Result: ${fireCount} < ${threshold}`);
    console.log('A');
  } else {
    console.log(`Result: ${fireCount} >= ${threshold}`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
